"""Corpus identity and witness bookkeeping.

A corpus identity is the entry plus the recovered input values.  Model
results, raw bytes after a string NUL, transport arguments, object order and
preparation metadata never take part.  Arrays, objects, booleans and integers
keep their JSON type identity, so an empty array and an empty object differ.
"""


def canonical(value):
    """A hashable, order-insensitive view of a recovered JSON value."""
    kind = value.__class__
    if kind is bool:
        return ("b", value)
    if kind is int:
        return ("i", value)
    if kind is str:
        return ("s", value)
    if kind is list:
        return ("a", tuple(canonical(item) for item in value))
    if kind is dict:
        return ("o", tuple(sorted((key, canonical(item))
                                  for key, item in value.items())))
    if value is None:
        return ("n",)
    return ("?", repr(value))


def identity_key(entry, names, values):
    """The corpus identity of one recovered run."""
    return (entry, tuple((name, canonical(values[name])) for name in names))


def make_hashable(obj):
    """Backwards compatible alias of `canonical`."""
    return canonical(obj)


